// CPTS arsenal page (generated by scripts/build-cpts.mjs). Adds copy buttons to
// the command blocks, a search over the tools (by port, service, tag or name),
// and the Cyber Kill Chain rail: click a stage to narrow to it, and the rail
// marks the stage you're reading. Without scripts the page is the whole
// reference, every tool expandable, every stage anchored.
import { initCommandPalette } from "../js/command-palette.js?v=search2";
import { initSiteHeader } from "../js/site-header.js?v=276fa973-header";
import { initTheme } from "../js/theme.js?v=276fa973";
import { copyTextToClipboard } from "../js/markdown.js?v=276fa973-th";
import { highlightAllIn } from "../js/highlight.js?v=276fa973";
import { initHeroDither } from "../js/hero-dither.js?v=276fa973-idle";

const COPY_ICON = '<svg class="writeup-code-copy-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M6 15H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v1"/></svg>';

// Highlight every command block and wrap it in the site's code-block shell
// (panel, language label, copy button, line-number gutter), the same markup
// the writeups use. Done here rather than with enhanceMarkdownBody because that
// also rewrites heading ids, which would collide with the build-time ones and
// break the stage headings' aria-labelledby.
const enhanceCode = () => {
  const bodies = document.querySelectorAll(".cpts-tool-body");
  for (const body of bodies) highlightAllIn(body);
  for (const pre of document.querySelectorAll(".cpts-tool-body pre")) {
    if (pre.closest(".writeup-code-block")) continue;
    const wrapper = document.createElement("div");
    wrapper.className = "writeup-code-block";
    pre.parentNode.insertBefore(wrapper, pre);

    const langSpan = pre.querySelector(".bt-code-lang");
    const language = langSpan?.textContent?.trim() || "";
    langSpan?.remove();

    const header = document.createElement("div");
    header.className = "writeup-code-header";
    const langLabel = document.createElement("span");
    langLabel.className = "writeup-code-lang";
    langLabel.textContent = language;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "writeup-code-copy";
    btn.innerHTML = COPY_ICON;
    const btnLabel = document.createElement("span");
    btnLabel.className = "writeup-code-copy-label";
    btnLabel.textContent = "Copy";
    btn.append(btnLabel);
    btn.addEventListener("click", () => {
      const code = pre.querySelector("code")?.textContent || pre.textContent || "";
      void copyTextToClipboard(code.trim(), btnLabel, "Copy");
    });
    header.append(langLabel, btn);

    const main = document.createElement("div");
    main.className = "writeup-code-main";
    const code = pre.querySelector("code");
    const lines = (code?.textContent ?? pre.textContent ?? "").replace(/\n$/, "").split("\n").length;
    if (lines >= 2) {
      main.classList.add("has-line-numbers");
      const gutter = document.createElement("span");
      gutter.className = "writeup-code-gutter";
      gutter.setAttribute("aria-hidden", "true");
      gutter.textContent = Array.from({ length: lines }, (_, i) => i + 1).join("\n");
      main.append(gutter);
    }
    main.append(pre);
    wrapper.append(header, main);
  }
};

// Stage checklists: remember each tick per viewer and keep the done/total
// count. localStorage is a per-viewer convenience, so every access is guarded
// and the page works the same if it is unavailable.
const CHECK_KEY = "cpts-checklist";
const loadChecks = () => {
  try { return JSON.parse(localStorage.getItem(CHECK_KEY)) || {}; } catch { return {}; }
};
const saveChecks = (state) => {
  try { localStorage.setItem(CHECK_KEY, JSON.stringify(state)); } catch { /* ignore */ }
};

const initChecklists = () => {
  const panels = [...document.querySelectorAll(".cpts-checklist")];
  if (!panels.length) return;
  const state = loadChecks();
  for (const panel of panels) {
    const stage = panel.dataset.stage;
    const boxes = [...panel.querySelectorAll('input[type="checkbox"]')];
    const countEl = panel.querySelector("[data-check-count]");
    const saved = state[stage] || {};
    for (const box of boxes) if (saved[box.dataset.idx]) box.checked = true;

    const update = () => {
      const done = boxes.filter((b) => b.checked).length;
      if (countEl) countEl.textContent = `${done}/${boxes.length}`;
      panel.classList.toggle("is-complete", done === boxes.length);
    };

    for (const box of boxes) {
      box.addEventListener("change", () => {
        const current = loadChecks();
        const forStage = current[stage] || {};
        if (box.checked) forStage[box.dataset.idx] = true;
        else delete forStage[box.dataset.idx];
        if (Object.keys(forStage).length) current[stage] = forStage;
        else delete current[stage];
        saveChecks(current);
        update();
      });
    }
    update();
  }
};

const initArsenal = () => {
  const input = document.getElementById("cpts-q");
  const countLabel = document.getElementById("cpts-count");
  const emptyNote = document.getElementById("cpts-empty");
  const stages = [...document.querySelectorAll(".cpts-stage")];
  const tools = [...document.querySelectorAll(".cpts-tool")];
  const railLinks = [...document.querySelectorAll(".cpts-rail-stage")];
  if (!stages.length) return;
  const total = tools.length;
  let stageFilter = "";
  // Each tool lives inside exactly one stage section, so counts come from the DOM.
  const toolsIn = (stage) => [...stage.querySelectorAll(".cpts-tool")];

  const paint = () => {
    const query = (input?.value || "").trim().toLowerCase();
    const words = query.split(/\s+/).filter(Boolean);
    for (const tool of tools) {
      const text = tool.dataset.search || "";
      tool.hidden = !words.every((word) => text.includes(word));
    }
    let shown = 0;
    for (const stage of stages) {
      const visibleIn = toolsIn(stage).filter((tool) => !tool.hidden).length;
      stage.hidden = (stageFilter && stage.dataset.stage !== stageFilter) || visibleIn === 0;
      if (!stage.hidden) shown += visibleIn;
    }
    for (const link of railLinks) {
      const id = link.dataset.stage;
      const badge = link.querySelector(".cpts-rail-count");
      if (badge) {
        const section = id ? stages.find((stage) => stage.dataset.stage === id) : null;
        badge.textContent = String(section ? toolsIn(section).filter((tool) => !tool.hidden).length : tools.filter((tool) => !tool.hidden).length);
      }
      link.classList.toggle("is-active", id === stageFilter);
    }
    if (countLabel) countLabel.textContent = query || stageFilter ? `${shown} of ${total} tools` : `${total} tools`;
    if (emptyNote) emptyNote.hidden = shown > 0;
  };

  input?.addEventListener("input", paint);

  for (const link of railLinks) {
    link.addEventListener("click", () => {
      // "All stages" (empty data-stage) clears; clicking the active stage clears too.
      const id = link.dataset.stage;
      stageFilter = id && id !== stageFilter ? id : "";
      paint();
      // let the anchor jump happen after the filter resolves which sections exist
      window.requestAnimationFrame(() => {
        const target = stageFilter ? document.getElementById(`stage-${stageFilter}`) : document.getElementById("cpts-main");
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });
  }

  // While browsing (no stage filter), mark the stage currently in view.
  if ("IntersectionObserver" in window) {
    const observer = new IntersectionObserver((entries) => {
      if (stageFilter) return;
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const id = entry.target.dataset.stage;
        for (const link of railLinks) link.classList.toggle("is-active", link.dataset.stage === id);
      }
    }, { rootMargin: "-20% 0px -70% 0px" });
    for (const stage of stages) observer.observe(stage);
  }

  paint();
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  initHeroDither();
  enhanceCode();
  initChecklists();
  initArsenal();
});
